import java.nio.file.*;import java.security.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Rejects duplicate canonical classes and byte-equivalent copied production implementations. */
public final class DuplicateProductionImplementationCheck{
 private static final Pattern PACKAGE=Pattern.compile("\\bpackage\\s+([\\w.]+)\\s*;"),TYPE=Pattern.compile("(?m)^\\s*(?:public\\s+)?(?:final\\s+|abstract\\s+|sealed\\s+|non-sealed\\s+)?(?:class|record|interface|enum)\\s+(\\w+)");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]);Map<String,Path>types=new HashMap<>(),hashes=new HashMap<>();List<String>failures=new ArrayList<>();try(var paths=Files.walk(root.resolve("server"))){for(Path path:paths.filter(Files::isRegularFile).filter(p->canonical(p.toString())).toList()){String body=Files.readString(path);String code=body.replaceAll("(?s)/\\*.*?\\*/"," ").replaceAll("(?m)//.*$"," ");Matcher pkg=PACKAGE.matcher(code),type=TYPE.matcher(code);if(!pkg.find()||!type.find())continue;String fqcn=pkg.group(1)+'.'+type.group(1);Path old=types.putIfAbsent(fqcn,path);if(old!=null)failures.add("duplicate type "+fqcn+": "+old+" / "+path);String normalized=code.replaceFirst("(?m)^\\s*package\\s+[\\w.]+\\s*;","package <canonical>;").replaceAll("\\s+"," ").trim();String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(normalized.getBytes(java.nio.charset.StandardCharsets.UTF_8)));old=hashes.putIfAbsent(hash,path);if(old!=null&&!old.equals(path))failures.add("copied implementation: "+old+" / "+path);}}Path out=root.resolve("work/audit/dead04-duplicate-implementations.txt");Files.createDirectories(out.getParent());Files.writeString(out,failures.isEmpty()?"DEAD04 passed: canonical production types and implementations are unique; API ownership collision gate remains authoritative for runtime entries.\n":String.join("\n",failures)+"\n");if(!failures.isEmpty())throw new IllegalStateException("duplicate production implementation gate failed: "+failures.size());System.out.println("Duplicate production implementation check passed: "+types.size()+" types.");}
 private static boolean canonical(String raw){String path=raw.replace('\\','/').toLowerCase(Locale.ROOT);return path.endsWith(".java")&&path.contains("/src/main/java/")&&!path.contains("/target/")&&!path.contains("/build/")&&!path.contains("/legacy/");}
}
